CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE member_role AS ENUM ('owner','manager','employee');
CREATE TYPE payment_method AS ENUM ('cash','mobile_money','bank_transfer','card','credit');
CREATE TYPE inventory_movement_type AS ENUM ('opening','purchase','sale','adjustment');

CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE CHECK (email=lower(email)), password_hash text NOT NULL, email_verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE businesses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 2 AND 160), country_code char(2) NOT NULL, currency_code char(3) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE business_members (business_id uuid NOT NULL REFERENCES businesses(id), user_id uuid NOT NULL REFERENCES users(id), role member_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(business_id,user_id));
CREATE TABLE customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), name text NOT NULL, phone text, email text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE suppliers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), name text NOT NULL, phone text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), name text NOT NULL, sku text, cost_price numeric(18,2) NOT NULL CHECK(cost_price>=0), selling_price numeric(18,2) NOT NULL CHECK(selling_price>=0), quantity integer NOT NULL CHECK(quantity>=0), minimum_stock integer NOT NULL DEFAULT 0 CHECK(minimum_stock>=0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(business_id,sku));
CREATE TABLE sales (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), idempotency_key uuid NOT NULL, customer_id uuid REFERENCES customers(id), payment_method payment_method NOT NULL, subtotal numeric(18,2) NOT NULL CHECK(subtotal>=0), discount numeric(18,2) NOT NULL DEFAULT 0 CHECK(discount>=0), total numeric(18,2) NOT NULL CHECK(total>=0), cost_total numeric(18,2) NOT NULL CHECK(cost_total>=0), sold_at timestamptz NOT NULL DEFAULT now(), created_by uuid NOT NULL REFERENCES users(id), UNIQUE(business_id,idempotency_key));
CREATE TABLE sale_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sale_id uuid NOT NULL REFERENCES sales(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES products(id), product_name text NOT NULL, quantity integer NOT NULL CHECK(quantity>0), unit_price numeric(18,2) NOT NULL CHECK(unit_price>=0), unit_cost numeric(18,2) NOT NULL CHECK(unit_cost>=0), line_total numeric(18,2) NOT NULL CHECK(line_total>=0));
CREATE TABLE inventory_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), product_id uuid NOT NULL REFERENCES products(id), movement_type inventory_movement_type NOT NULL, quantity_delta integer NOT NULL, reference_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE expenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), category text NOT NULL, amount numeric(18,2) NOT NULL CHECK(amount>=0), payment_method payment_method NOT NULL, description text, spent_at timestamptz NOT NULL DEFAULT now(), created_by uuid NOT NULL REFERENCES users(id));
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses(id), customer_id uuid NOT NULL REFERENCES customers(id), amount numeric(18,2) NOT NULL CHECK(amount>0), paid_at timestamptz NOT NULL DEFAULT now(), created_by uuid NOT NULL REFERENCES users(id));
CREATE TABLE audit_logs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, business_id uuid REFERENCES businesses(id), user_id uuid REFERENCES users(id), action text NOT NULL, entity_type text NOT NULL, entity_id uuid, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX products_business_idx ON products(business_id); CREATE INDEX sales_business_sold_idx ON sales(business_id,sold_at DESC); CREATE INDEX expenses_business_spent_idx ON expenses(business_id,spent_at DESC); CREATE INDEX customers_business_idx ON customers(business_id); CREATE INDEX inventory_business_idx ON inventory_movements(business_id,product_id);

CREATE FUNCTION is_business_member(target_business uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT EXISTS(SELECT 1 FROM business_members WHERE business_id=target_business AND user_id::text=current_setting('app.user_id',true)) $$;
ALTER TABLE businesses ENABLE ROW LEVEL SECURITY; ALTER TABLE business_members ENABLE ROW LEVEL SECURITY; ALTER TABLE customers ENABLE ROW LEVEL SECURITY; ALTER TABLE suppliers ENABLE ROW LEVEL SECURITY; ALTER TABLE products ENABLE ROW LEVEL SECURITY; ALTER TABLE sales ENABLE ROW LEVEL SECURITY; ALTER TABLE sale_items ENABLE ROW LEVEL SECURITY; ALTER TABLE inventory_movements ENABLE ROW LEVEL SECURITY; ALTER TABLE expenses ENABLE ROW LEVEL SECURITY; ALTER TABLE payments ENABLE ROW LEVEL SECURITY; ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY business_member_read ON businesses FOR SELECT USING (is_business_member(id));
CREATE POLICY member_self_read ON business_members FOR SELECT USING (user_id::text=current_setting('app.user_id',true));
CREATE POLICY customers_tenant ON customers USING(is_business_member(business_id)) WITH CHECK(is_business_member(business_id));
CREATE POLICY suppliers_tenant ON suppliers USING(is_business_member(business_id)) WITH CHECK(is_business_member(business_id));
CREATE POLICY products_tenant ON products USING(is_business_member(business_id)) WITH CHECK(is_business_member(business_id));
CREATE POLICY sales_tenant ON sales USING(is_business_member(business_id)) WITH CHECK(is_business_member(business_id));
CREATE POLICY items_tenant ON sale_items USING(EXISTS(SELECT 1 FROM sales s WHERE s.id=sale_id AND is_business_member(s.business_id))) WITH CHECK(EXISTS(SELECT 1 FROM sales s WHERE s.id=sale_id AND is_business_member(s.business_id)));
CREATE POLICY moves_tenant ON inventory_movements USING(is_business_member(business_id)) WITH CHECK(is_business_member(business_id));
CREATE POLICY expenses_tenant ON expenses USING(is_business_member(business_id)) WITH CHECK(is_business_member(business_id));
CREATE POLICY payments_tenant ON payments USING(is_business_member(business_id)) WITH CHECK(is_business_member(business_id));
CREATE POLICY audit_tenant ON audit_logs FOR SELECT USING(is_business_member(business_id));
